36	function useScrolled(threshold = 50) {
37	  const [scrolled, setScrolled] = useState(false);
38	  useEffect(() => {
39	    const handler = () => setScrolled(window.scrollY > threshold);
40	    window.addEventListener("scroll", handler, { passive: true });
41	    return () => window.removeEventListener("scroll", handler);
42	  }, [threshold]);
43	  return scrolled;
44	}
45	
46	function useInView(options?: IntersectionObserverInit) {
47	  const ref = useRef<HTMLDivElement>(null);
48	  const [inView, setInView] = useState(false);
49	  useEffect(() => {
50	    if (!ref.current) return;
51	    const obs = new IntersectionObserver(
52	      ([e]) => {
53	        if (e.isIntersecting) {
54	          setInView(true);
55	          obs.disconnect();
56	        }
57	      },
58	      { threshold: 0.12, ...options }
59	    );
60	    obs.observe(ref.current);
61	    return () => obs.disconnect();
62	  }, [options]);
63	  return { ref, inView };
64	}
